const KEY='savedatcost-workbench-v1';
const icons={Overview:'⌂',Transactions:'≡',Accounts:'▣',Budget:'◒',Savings:'◎',Investments:'↗',Recurring:'↻',Reports:'▥',Settings:'⚙'};
const seed={accounts:[],transactions:[],budgets:[],goals:[],investments:[],recurring:[]};
let state=JSON.parse(localStorage.getItem(KEY)||'null')||seed;if(!localStorage.getItem(KEY+'-empty-reset-v1')){localStorage.removeItem(KEY);localStorage.removeItem(KEY+'-backup');localStorage.setItem(KEY+'-empty-reset-v1','1');state=JSON.parse(JSON.stringify(seed))}let current='Overview';let review=false;let query='';const month='2026-10';
const money=n=>new Intl.NumberFormat('en-PH',{style:'currency',currency:'PHP',maximumFractionDigits:2}).format(n||0);const dateFmt=s=>new Date(s+'T00:00:00').toLocaleDateString('en-PH',{month:'short',day:'numeric'});
function save(){localStorage.setItem(KEY,JSON.stringify(state));document.getElementById('backupLabel').textContent='Saved just now'}
function accountBalance(id){const a=state.accounts.find(x=>x.id===id);return(a?.opening||0)+state.transactions.filter(t=>t.account===id).reduce((s,t)=>s+(t.type==='income'||(t.type==='transfer'&&t.direction==='in')?t.amount:-t.amount),0)}
function totalCash(){return state.accounts.reduce((s,a)=>s+accountBalance(a.id),0)}function income(){return state.transactions.filter(t=>t.type==='income'&&t.date.startsWith(month)).reduce((s,t)=>s+t.amount,0)}function expenses(){return state.transactions.filter(t=>t.type==='expense'&&t.date.startsWith(month)).reduce((s,t)=>s+t.amount,0)}function investmentValue(){return state.investments.reduce((s,i)=>s+i.units*i.price,0)}function budgetSpent(c){return state.transactions.filter(t=>t.type==='expense'&&t.category===c&&t.date.startsWith(month)).reduce((s,t)=>s+t.amount,0)}
function nav(){document.getElementById('nav').innerHTML=Object.keys(icons).map(k=>`<button class="nav-item ${current===k?'active':''}" data-view="${k}"><span class="nav-icon">${icons[k]}</span><span>${k}</span></button>`).join('');document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{current=b.dataset.view;render()})}
function stat(label,value,meta,negative=false){return`<div class="stat-card"><div class="label"><span>${label}</span><span>↗</span></div><div class="value">${value}</div><div class="meta ${negative?'negative':''}">${meta}</div></div>`}
function activity(list){if(!list.length)return'<div class="empty"><strong>No activity yet</strong>Add your first transaction to see it here.</div>';return`<div class="activity-list">${list.map(t=>{const sign=t.type==='income'?'+':t.type==='transfer'?'':'−';const cls=t.type==='income'?'income':t.type==='expense'?'expense':'neutral';return`<div class="activity-row"><div class="activity-icon">${t.type==='income'?'↙':t.type==='transfer'?'↔':'•'}</div><div class="activity-main"><strong>${t.description}</strong><small>${dateFmt(t.date)} · ${t.category}</small></div><span class="amount ${cls}">${sign}${money(t.amount)}</span></div>`}).join('')}</div>`}
function dashboard(){const recent=state.transactions.filter(t=>!query||`${t.description} ${t.category}`.toLowerCase().includes(query.toLowerCase())).sort((a,b)=>b.date.localeCompare(a.date)).slice(0,6);const g=state.goals[0]||{name:'Create a goal',current:0,target:1};return`<div class="view-head"><div><div class="kicker">October 2026 · local workspace</div><h1>Your money, in focus.</h1><p>A calm place to see what came in, what went out, and what matters next.</p></div><div class="view-actions"><div class="mode-toggle"><button class="${!review?'active':''}" onclick="setMode(false)">Simple</button><button class="${review?'active':''}" onclick="setMode(true)">Review</button></div></div></div><div class="grid grid-4">${stat('Available across accounts',money(totalCash()),'All local accounts')}${stat('Money in',money(income()),'This month')}${stat('Money out',money(expenses()),'This month',true)}${stat('Investments',money(investmentValue()),'Current value')}</div><div class="grid grid-2 section-gap"><div class="panel"><div class="panel-head"><h2>Recent activity</h2><button onclick="go('Transactions')">View all →</button></div>${activity(recent)}</div><div class="panel"><div class="panel-head"><h2>Monthly budget</h2><button onclick="go('Budget')">Open budget →</button></div>${state.budgets.map(b=>`<div class="budget-row"><div class="budget-label"><strong>${b.category}</strong><span>${money(budgetSpent(b))} / ${money(b.limit)}</span></div><div class="bar"><span style="width:${Math.min(100,budgetSpent(b)/b.limit*100)}%;background:${budgetSpent(b)>b.limit?'var(--red)':'var(--accent)'}"></span></div></div>`).join('')}</div></div><div class="grid grid-3 section-gap"><div class="goal-card"><span class="muted">Next milestone</span><h3>${g.name}</h3><div class="bar"><span style="width:${Math.min(100,g.current/g.target*100)}%"></span></div><div class="goal-foot"><span>${money(g.current)} saved</span><strong>${Math.round(g.current/g.target*100)}%</strong></div></div><div class="panel"><div class="panel-head"><h2>Savings pulse</h2><span>Goal progress</span></div><div class="metric-line"><span>Emergency fund</span><strong>${money(g.current)}</strong></div><div class="metric-line"><span>Monthly savings target</span><strong>${money(5000)}</strong></div><div class="metric-line"><span>Savings rate</span><strong>${income()?Math.round((income()-expenses())/income()*100):0}%</strong></div></div><div class="panel"><div class="panel-head"><h2>Money flow</h2><span>Last 6 months</span></div><div class="mini-chart"><i style="height:40%"></i><i style="height:58%"></i><i style="height:52%"></i><i style="height:72%"></i><i style="height:67%"></i><i style="height:88%"></i></div><div class="mini-axis"><span>May</span><span>Oct</span></div></div></div>`}
function transactions(){const list=state.transactions.filter(t=>!query||`${t.description} ${t.category}`.toLowerCase().includes(query.toLowerCase())).sort((a,b)=>b.date.localeCompare(a.date));return`<div class="view-head"><div><div class="kicker">Ledger</div><h1>Transactions</h1><p>Every peso has a place. Add, review, and understand your daily activity.</p></div><button class="primary-button" onclick="openModal()">＋ Add transaction</button></div><div class="panel"><div class="panel-head"><h2>${list.length} recorded entries</h2><span>October 2026</span></div><div class="table-wrap"><table class="table"><thead><tr><th>Date</th><th>Description</th><th>Category</th><th>Account</th><th>Type</th><th>Amount</th></tr></thead><tbody>${list.map(t=>`<tr><td>${dateFmt(t.date)}</td><td><strong>${t.description}</strong></td><td>${t.category}</td><td>${state.accounts.find(a=>a.id===t.account)?.name||'—'}</td><td><span class="badge ${t.type==='income'?'green':t.type==='expense'?'orange':''}">${t.type}</span></td><td class="amount ${t.type==='income'?'income':t.type==='expense'?'expense':''}">${t.type==='income'?'+':t.type==='expense'?'−':''}${money(t.amount)}</td></tr>`).join('')}</tbody></table></div></div>`}
function accounts(){return`<div class="view-head"><div><div class="kicker">Where money lives</div><h1>Accounts</h1><p>Bank accounts, e-wallets, and cash—kept visible and reconciled.</p></div><button class="primary-button" onclick="addAccount()">＋ Add account</button></div><div class="grid grid-3">${state.accounts.map(a=>`<div class="account-card"><div class="account-top"><div><h3>${a.name}</h3><small>${a.type}</small></div><span class="badge green">active</span></div><div class="balance">${money(accountBalance(a.id))}</div><small>Opening ${money(a.opening)} · derived from ledger</small></div>`).join('')}</div><div class="panel section-gap"><div class="panel-head"><h2>Balance integrity</h2><span>Review mode available</span></div><div class="metric-line"><span>Total across accounts</span><strong>${money(totalCash())}</strong></div><div class="metric-line"><span>Last local backup</span><strong>Just now</strong></div><div class="notice">Balances are calculated from opening balances plus your transaction history. Transfers are kept separate from income and expenses.</div></div>`}
function budget(){const planned=state.budgets.reduce((s,b)=>s+b.limit,0);return`<div class="view-head"><div><div class="kicker">October 2026</div><h1>Budget</h1><p>Simple category limits with a clear view of what remains.</p></div><button class="primary-button" onclick="addBudget()">＋ Add category</button></div><div class="grid grid-4">${stat('Planned',money(planned),'Monthly limits')}${stat('Spent',money(expenses()),'This month',true)}${stat('Remaining',money(planned-expenses()),'Before overspend')}${stat('Savings rate',`${income()?Math.round((income()-expenses())/income()*100):0}%`,'Based on income')}</div><div class="panel section-gap">${state.budgets.map(b=>`<div class="budget-row"><div class="budget-label"><strong>${b.category}</strong><span>${money(budgetSpent(b))} spent · ${money(Math.max(0,b.limit-budgetSpent(b)))} left</span></div><div class="bar"><span style="width:${Math.min(100,budgetSpent(b)/b.limit*100)}%;background:${budgetSpent(b)>b.limit?'var(--red)':'var(--accent)'}"></span></div></div>`).join('')}</div>`}
function savings(){return`<div class="view-head"><div><div class="kicker">Build your buffer</div><h1>Savings goals</h1><p>Small, consistent contributions become options later.</p></div><button class="primary-button" onclick="addGoal()">＋ Add goal</button></div><div class="grid grid-2">${state.goals.map(g=>`<div class="panel"><div class="panel-head"><h2>${g.name}</h2><span>${Math.round(g.current/g.target*100)}%</span></div><div class="bar"><span style="width:${Math.min(100,g.current/g.target*100)}%;background:var(--green)"></span></div><div class="metric-line"><span>Saved</span><strong>${money(g.current)}</strong></div><div class="metric-line"><span>Target</span><strong>${money(g.target)}</strong></div><div class="metric-line"><span>Target date</span><strong>${new Date(g.due).toLocaleDateString('en-PH',{month:'short',year:'numeric'})}</strong></div></div>`).join('')}</div>`}
function investments(){const contributed=state.investments.reduce((s,i)=>s+i.cost,0);return`<div class="view-head"><div><div class="kicker">Long-term view</div><h1>Investments</h1><p>A beginner-friendly record of what you own and why it matters over time.</p></div><button class="primary-button" onclick="addInvestment()">＋ Add holding</button></div><div class="grid grid-4">${stat('Current value',money(investmentValue()),'Manual prices')}${stat('Contributed',money(contributed),'Total cost')}${stat('Gain / loss',money(investmentValue()-contributed),investmentValue()>=contributed?'Positive movement':'Review movement',investmentValue()<contributed)}${stat('Holdings',state.investments.length,'Keep it simple')}</div><div class="panel section-gap"><div class="panel-head"><h2>Holdings</h2><span>Prices are entered by you</span></div><div class="table-wrap"><table class="table"><thead><tr><th>Holding</th><th>Type</th><th>Units</th><th>Cost basis</th><th>Current price</th><th>Value</th></tr></thead><tbody>${state.investments.map(i=>`<tr><td><strong>${i.name}</strong></td><td>${i.kind}</td><td>${i.units}</td><td>${money(i.cost)}</td><td>${money(i.price)}</td><td><strong>${money(i.units*i.price)}</strong></td></tr>`).join('')}</tbody></table></div><div class="notice">This tracker is not investment advice. It records your contributions and manually entered prices so you can observe long-term progress.</div></div>`}
function reports(){return`<div class="view-head"><div><div class="kicker">Understand the pattern</div><h1>Reports</h1><p>Lightweight views that help you notice habits without overwhelming you.</p></div></div><div class="grid grid-2"><div class="panel"><div class="panel-head"><h2>Monthly summary</h2><span>October 2026</span></div><div class="metric-line"><span>Money in</span><strong class="amount income">${money(income())}</strong></div><div class="metric-line"><span>Money out</span><strong class="amount expense">${money(expenses())}</strong></div><div class="metric-line"><span>Net movement</span><strong>${money(income()-expenses())}</strong></div><div class="metric-line"><span>Available cash</span><strong>${money(totalCash())}</strong></div></div><div class="panel"><div class="panel-head"><h2>By category</h2><span>Money out</span></div>${state.budgets.map(b=>`<div class="metric-line"><span>${b.category}</span><strong>${money(budgetSpent(b))}</strong></div>`).join('')}</div></div>`}
function settings(){return`<div class="view-head"><div><div class="kicker">Your workspace</div><h1>Settings</h1><p>Keep the app comfortable, private, and easy to recover.</p></div></div><div class="grid grid-2"><div class="panel"><div class="panel-head"><h2>Appearance</h2></div><div class="metric-line"><span>Theme</span><button class="ghost-button" onclick="toggleTheme()">Toggle light / dark</button></div><div class="metric-line"><span>Detail mode</span><button class="ghost-button" onclick="setMode(!review)">${review?'Review':'Simple'}</button></div></div><div class="panel"><div class="panel-head"><h2>Data safety</h2></div><div class="metric-line"><span>Storage</span><strong>Local browser storage</strong></div><div class="metric-line"><span>Export data</span><button class="ghost-button" onclick="exportData()">Download JSON</button></div><div class="metric-line"><span>Reset demo data</span><button class="ghost-button" onclick="resetData()">Reset</button></div><div class="notice">Online sync is intentionally optional. Your data stays on this device until you choose to export or sync it.</div></div></div>`}
function render(){nav();document.body.classList.toggle('review-mode',review);document.getElementById('eyebrow').textContent=current;document.getElementById('pageTitle').textContent=current==='Overview'?'Your money, in focus':current;const views={Overview:dashboard,Transactions:transactions,Accounts:accounts,Budget:budget,Savings:savings,Investments:investments,Reports:reports,Settings:settings};document.getElementById('app').innerHTML=views[current]();if(current==='Settings')document.getElementById('app').insertAdjacentHTML('beforeend',managePanel());}
function go(v){current=v;render()}function setMode(v){review=v;render()}function toggleTheme(){document.body.classList.toggle('dark');localStorage.setItem('ledger-theme',document.body.classList.contains('dark')?'dark':'light')}function closeModal(){document.getElementById('modalRoot').innerHTML=''}
function openModal(){document.getElementById('modalRoot').innerHTML=`<div class="modal-backdrop" onclick="if(event.target===this)closeModal()"><div class="modal"><div class="modal-head"><div><h2>Add transaction</h2><p>Record it once. Ledger keeps the totals honest.</p></div><button class="close" onclick="closeModal()">×</button></div><form id="txForm"><div class="form-grid"><div class="field"><label>Date</label><input name="date" type="date" value="2026-10-10" required></div><div class="field"><label>Type</label><select name="type"><option value="expense">Money out</option><option value="income">Money in</option><option value="transfer">Transfer</option></select></div><div class="field full"><label>Description</label><input name="description" placeholder="e.g. Lunch, salary, rent" required></div><div class="field"><label>Category</label><input name="category" placeholder="Food" required></div><div class="field"><label>Amount · PHP</label><input name="amount" type="number" min="0.01" step="0.01" placeholder="0.00" required></div><div class="field full"><label>Account</label><select name="account">${state.accounts.map(a=>`<option value="${a.id}">${a.name}</option>`).join('')}</select></div></div><div class="modal-actions"><button type="button" class="ghost-button" onclick="closeModal()">Cancel</button><button class="primary-button">Save transaction</button></div></form></div></div>`;document.getElementById('txForm').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);state.transactions.push({id:'t'+Date.now(),date:f.get('date'),description:f.get('description'),category:f.get('category'),account:f.get('account'),type:f.get('type'),amount:Number(f.get('amount'))});save();closeModal();current='Transactions';render()}}
function addAccount(){const name=prompt('Account name');if(!name)return;state.accounts.push({id:'a'+Date.now(),name,type:'Bank or wallet',opening:0});save();render()}function addBudget(){const category=prompt('Category name');if(!category)return;const limit=Number(prompt('Monthly limit in PHP','1000'));if(!limit)return;state.budgets.push({category,limit});save();render()}function addGoal(){const name=prompt('Goal name');if(!name)return;const target=Number(prompt('Target amount in PHP','10000'));if(!target)return;state.goals.push({id:'g'+Date.now(),name,target,current:0,due:'2027-12-31'});save();render()}function addInvestment(){const name=prompt('Holding name');if(!name)return;const cost=Number(prompt('Amount contributed in PHP','1000'));if(!cost)return;state.investments.push({id:'i'+Date.now(),name,kind:'Investment',units:1,cost,price:cost});save();render()}
function exportData(){const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='ledger-backup.json';a.click();URL.revokeObjectURL(a.href)}function resetData(){if(confirm('Reset Ledger to the sample workspace?')){state=JSON.parse(JSON.stringify(seed));save();render()}}
document.getElementById('quickAdd').onclick=openModal;document.getElementById('settingsBtn').onclick=()=>go('Settings');document.getElementById('syncBtn').onclick=()=>alert('Local-first mode is active. Optional encrypted sync can be connected later.');document.getElementById('searchInput').oninput=e=>{query=e.target.value;render()};document.getElementById('themeToggle').onclick=toggleTheme;if(localStorage.getItem('ledger-theme')==='dark')document.body.classList.add('dark');render();

function managerActions(type,id){return`<button class="edit-button" onclick="editRecord('${type}','${id}')">Edit</button><button class="edit-button danger" onclick="deleteRecord('${type}','${id}')">Delete</button>`}
function managePanel(){const accountName=id=>state.accounts.find(a=>a.id===id)?.name||'—';return`<div class="panel manager-panel section-gap"><div class="panel-head"><div><h2>Edit your data</h2><span>Changes save automatically on this device.</span></div><span>In-app editor</span></div><div class="manager-group"><h3>Transactions</h3><table class="manager-table">${state.transactions.map(t=>`<tr><td>${dateFmt(t.date)} · <strong>${t.description}</strong><br><span class="muted">${t.category} · ${accountName(t.account)}</span></td><td>${money(t.amount)}</td><td>${managerActions('transaction',t.id)}</td></tr>`).join('')}</table></div><div class="manager-group"><h3>Accounts</h3><table class="manager-table">${state.accounts.map(a=>`<tr><td><strong>${a.name}</strong><br><span class="muted">${a.type}</span></td><td>${money(accountBalance(a.id))}</td><td>${managerActions('account',a.id)}</td></tr>`).join('')}</table></div><div class="manager-group"><h3>Budgets</h3><table class="manager-table">${state.budgets.map((b,i)=>`<tr><td><strong>${b.category}</strong></td><td>${money(b.limit)} / month</td><td>${managerActions('budget',String(i))}</td></tr>`).join('')}</table></div><div class="manager-group"><h3>Savings goals</h3><table class="manager-table">${state.goals.map(g=>`<tr><td><strong>${g.name}</strong></td><td>${money(g.current)} / ${money(g.target)}</td><td>${managerActions('goal',g.id)}</td></tr>`).join('')}</table></div><div class="manager-group"><h3>Investments</h3><table class="manager-table">${state.investments.map(i=>`<tr><td><strong>${i.name}</strong></td><td>${money(i.units*i.price)}</td><td>${managerActions('investment',i.id)}</td></tr>`).join('')}</table></div></div>`}
function field(label,name,value,type='text',full=false){return`<div class="field ${full?'full':''}"><label>${label}</label><input name="${name}" type="${type}" value="${String(value??'').replace(/"/g,'&quot;')}" ${type==='number'?'step="0.01" min="0"':''} required></div>`}
function editRecord(type,id){let r=type==='budget'?state.budgets[Number(id)]:type==='transaction'?state.transactions.find(x=>x.id===id):type==='account'?state.accounts.find(x=>x.id===id):type==='goal'?state.goals.find(x=>x.id===id):state.investments.find(x=>x.id===id);if(!r)return;let title='',fields='';if(type==='transaction'){title='Edit transaction';fields=field('Date','date',r.date,'date')+field('Type','type',r.type)+field('Description','description',r.description,'text',true)+field('Category','category',r.category)+field('Amount · PHP','amount',r.amount,'number')+`<div class="field full"><label>Account</label><select name="account">${state.accounts.map(a=>`<option value="${a.id}" ${a.id===r.account?'selected':''}>${a.name}</option>`).join('')}</select></div>`}else if(type==='account'){title='Edit account';fields=field('Account name','name',r.name,'text',true)+field('Type','type',r.type)+field('Opening balance · PHP','opening',r.opening,'number')}else if(type==='budget'){title='Edit budget category';fields=field('Category','category',r.category,'text',true)+field('Monthly limit · PHP','limit',r.limit,'number')}else if(type==='goal'){title='Edit savings goal';fields=field('Goal name','name',r.name,'text',true)+field('Target · PHP','target',r.target,'number')+field('Saved · PHP','current',r.current,'number')+field('Target date','due',r.due,'date')}else{title='Edit investment';fields=field('Holding name','name',r.name,'text',true)+field('Type','kind',r.kind)+field('Units','units',r.units,'number')+field('Cost basis · PHP','cost',r.cost,'number')+field('Current price · PHP','price',r.price,'number')};document.getElementById('modalRoot').innerHTML=`<div class="modal-backdrop" onclick="if(event.target===this)closeModal()"><div class="modal"><div class="modal-head"><div><h2>${title}</h2><p>Update the record and Ledger will recalculate the workspace.</p></div><button class="close" onclick="closeModal()">×</button></div><form id="editForm"><div class="form-grid">${fields}</div><div class="modal-actions"><button type="button" class="ghost-button" onclick="closeModal()">Cancel</button><button class="primary-button">Save changes</button></div></form></div></div>`;document.getElementById('editForm').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);if(type==='transaction'){Object.assign(r,{date:f.get('date'),type:f.get('type'),description:f.get('description'),category:f.get('category'),account:f.get('account'),amount:Number(f.get('amount'))})}else if(type==='account'){Object.assign(r,{name:f.get('name'),type:f.get('type'),opening:Number(f.get('opening'))})}else if(type==='budget'){Object.assign(r,{category:f.get('category'),limit:Number(f.get('limit'))})}else if(type==='goal'){Object.assign(r,{name:f.get('name'),target:Number(f.get('target')),current:Number(f.get('current')),due:f.get('due')})}else{Object.assign(r,{name:f.get('name'),kind:f.get('kind'),units:Number(f.get('units')),cost:Number(f.get('cost')),price:Number(f.get('price'))})}save();closeModal();render()}}
function deleteRecord(type,id){if(type==='account'&&state.transactions.some(t=>t.account===id)){alert('This account has transactions. Edit or move those transactions before deleting the account.');return}if(!confirm('Delete this record? This cannot be undone.'))return;if(type==='transaction')state.transactions=state.transactions.filter(t=>t.id!==id);if(type==='account')state.accounts=state.accounts.filter(a=>a.id!==id);if(type==='budget')state.budgets.splice(Number(id),1);if(type==='goal')state.goals=state.goals.filter(g=>g.id!==id);if(type==='investment')state.investments=state.investments.filter(i=>i.id!==id);save();render()}

let toastTimer;
function showToast(message,detail=''){clearTimeout(toastTimer);document.querySelector('.toast')?.remove();const el=document.createElement('div');el.className='toast';el.innerHTML=`${message}${detail?`<small>${detail}</small>`:''}`;document.body.appendChild(el);toastTimer=setTimeout(()=>el.remove(),2600)}
function save(){localStorage.setItem(KEY,JSON.stringify(state));document.getElementById('backupLabel').textContent='Saved just now';showToast('Saved','Your changes are stored on this device.')}
function modalShell(title,subtitle,fields,formId='entityForm'){document.getElementById('modalRoot').innerHTML=`<div class="modal-backdrop" onclick="if(event.target===this)closeModal()"><div class="modal"><div class="modal-head"><div><h2>${title}</h2><p>${subtitle}</p></div><button class="close" onclick="closeModal()">×</button></div><form id="${formId}"><div class="form-grid">${fields}</div><div class="modal-actions"><button type="button" class="ghost-button" onclick="closeModal()">Cancel</button><button class="primary-button">Save changes</button></div></form></div></div>`}
function selectField(label,name,options,value,full=false){return`<div class="field ${full?'full':''}"><label>${label}</label><select name="${name}">${options.map(o=>`<option value="${o[0]}" ${String(o[0])===String(value)?'selected':''}>${o[1]}</option>`).join('')}</select></div>`}
function transactionFields(r={}){return field('Date','date',r.date||'2026-10-10','date')+selectField('What happened?','type',[['expense','Money out'],['income','Money in'],['transfer','Move between accounts']],r.type||'expense')+field('Description','description',r.description||'','text',true)+field('Category','category',r.category||'Food')+field('Amount · PHP','amount',r.amount||'','number')+selectField('Account','account',state.accounts.map(a=>[a.id,a.name]),r.account||state.accounts[0]?.id,true)+selectField('Transfer direction','direction',[['out','Leaving this account'],['in','Arriving in this account']],r.direction||'out',true)+`<div class="field full"><p class="help-copy">Use “Move between accounts” for transfers. It will not count as income or spending.</p></div>`}
function openModal(){modalShell('Add transaction','A few details is all Ledger needs to keep your totals accurate.',transactionFields());document.getElementById('entityForm').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);state.transactions.push({id:'t'+Date.now(),date:f.get('date'),description:f.get('description'),category:f.get('category'),account:f.get('account'),type:f.get('type'),direction:f.get('direction'),amount:Number(f.get('amount'))});save();closeModal();current='Transactions';render()}}
function openEntityModal(type,id=null){const isNew=id===null;let r=type==='budget'?(isNew?{}:state.budgets[Number(id)]):type==='transaction'?(isNew?{}:state.transactions.find(x=>x.id===id)):type==='account'?(isNew?{}:state.accounts.find(x=>x.id===id)):type==='goal'?(isNew?{}:state.goals.find(x=>x.id===id)):isNew?{}:state.investments.find(x=>x.id===id);if(!r)return;let title=isNew?'Add ':'Edit ';let fields='';if(type==='transaction'){title+='transaction';fields=transactionFields(r)}else if(type==='account'){title+='account';fields=field('Account name','name',r.name||'','text',true)+bankProviderField(r.provider||'other')+selectField('Account type','type',[['Bank account','Bank account'],['E-wallet','E-wallet'],['Cash','Cash']],r.type||'Bank account')+field('Opening balance · PHP','opening',r.opening||0,'number')}else if(type==='budget'){title+='budget category';fields=field('Category name','category',r.category||'','text',true)+field('Monthly limit · PHP','limit',r.limit||'','number')}else if(type==='goal'){title+='savings goal';fields=field('Goal name','name',r.name||'','text',true)+field('Target amount · PHP','target',r.target||'','number')+field('Already saved · PHP','current',r.current||0,'number')+field('Target date','due',r.due||'2027-12-31','date')}else{title+='investment holding';fields=field('Holding name','name',r.name||'','text',true)+selectField('Investment type','kind',[['Fund','Fund'],['Stock','Stock'],['Bond','Bond'],['Time deposit','Time deposit'],['Other','Other']],r.kind||'Fund')+field('Units','units',r.units||1,'number')+field('Amount contributed · PHP','cost',r.cost||'','number')+field('Current price · PHP','price',r.price||'','number')};modalShell(title,'Make a change here and SavedatCost will recalculate the rest.',fields);document.getElementById('entityForm').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);let item=r;if(isNew){item={id:type[0]+Date.now()};if(type==='budget')state.budgets.push(item);else if(type==='transaction')state.transactions.push(item);else if(type==='account')state.accounts.push(item);else if(type==='goal')state.goals.push(item);else state.investments.push(item)}if(type==='transaction')Object.assign(item,{date:f.get('date'),type:f.get('type'),description:f.get('description'),category:f.get('category'),account:f.get('account'),direction:f.get('direction'),amount:Number(f.get('amount'))});if(type==='account')Object.assign(item,{name:f.get('name'),provider:f.get('provider')||'other',type:f.get('type'),opening:Number(f.get('opening'))});if(type==='budget')Object.assign(item,{category:f.get('category'),limit:Number(f.get('limit'))});if(type==='goal')Object.assign(item,{name:f.get('name'),target:Number(f.get('target')),current:Number(f.get('current')),due:f.get('due')});if(type==='investment')Object.assign(item,{name:f.get('name'),kind:f.get('kind'),units:Number(f.get('units')),cost:Number(f.get('cost')),price:Number(f.get('price'))});save();closeModal();render()}}
function addAccount(){openEntityModal('account')}function addBudget(){openEntityModal('budget')}function addGoal(){openEntityModal('goal')}function addInvestment(){openEntityModal('investment')}function editRecord(type,id){openEntityModal(type,type==='budget'?Number(id):id)}
function managePanel(){const accountName=id=>state.accounts.find(a=>a.id===id)?.name||'—';return`<details class="panel manager-details section-gap"><summary><div><h2>Edit your data</h2><p class="help-copy">Open this only when you need to correct or remove an existing record. New records use the buttons on each page.</p></div><span>In-app editor</span></summary><div class="manager-content"><div class="manager-group"><h3>Transactions</h3><table class="manager-table">${state.transactions.map(t=>`<tr><td>${dateFmt(t.date)} · <strong>${t.description}</strong><br><span class="muted">${t.category} · ${accountName(t.account)}</span></td><td>${money(t.amount)}</td><td>${managerActions('transaction',t.id)}</td></tr>`).join('')}</table></div><div class="manager-group"><h3>Accounts</h3><table class="manager-table">${state.accounts.map(a=>`<tr><td><strong>${a.name}</strong><br><span class="muted">${a.type}</span></td><td>${money(accountBalance(a.id))}</td><td>${managerActions('account',a.id)}</td></tr>`).join('')}</table></div><div class="manager-group"><h3>Budgets</h3><table class="manager-table">${state.budgets.map((b,i)=>`<tr><td><strong>${b.category}</strong></td><td>${money(b.limit)} / month</td><td>${managerActions('budget',String(i))}</td></tr>`).join('')}</table></div><div class="manager-group"><h3>Savings goals</h3><table class="manager-table">${state.goals.map(g=>`<tr><td><strong>${g.name}</strong></td><td>${money(g.current)} / ${money(g.target)}</td><td>${managerActions('goal',g.id)}</td></tr>`).join('')}</table></div><div class="manager-group"><h3>Investments</h3><table class="manager-table">${state.investments.map(i=>`<tr><td><strong>${i.name}</strong></td><td>${money(i.units*i.price)}</td><td>${managerActions('investment',i.id)}</td></tr>`).join('')}</table></div></div></details>`}
function quickActions(){return`<div class="panel section-gap"><div class="panel-head"><div><h2>What would you like to do?</h2><p class="help-copy">Keep your routine simple: record today, then check what is left.</p></div><span>Quick actions</span></div><div class="quick-actions"><button class="primary-button" onclick="openModal()">＋ Add expense</button><button class="ghost-button" onclick="openEntityModal('goal')">＋ Start savings goal</button><button class="ghost-button" onclick="go('Budget')">Review budget →</button><button class="ghost-button" onclick="go('Accounts')">Check accounts →</button></div></div>`}

