function accounts(){return`<div class="view-head"><div><div class="kicker">Where money lives</div><h1>Accounts</h1><p>Bank accounts, e-wallets, and cash—kept visible and easy to check.</p></div><button class="primary-button" onclick="addAccount()">＋ Add account</button></div><div class="grid grid-3">${state.accounts.map(a=>{const p=providerInfo(a.provider);return`<div class="account-card"><div class="account-top"><div class="account-identity">${accountBrand(a)}<div><h3>${a.name}</h3><small>${p.label} · ${a.type}</small></div></div><span class="badge green">active</span></div><div class="balance">${money(accountBalance(a.id))}</div><small>Opening ${money(a.opening)} · derived from ledger</small><button class="ghost-button" style="margin-top:15px;width:100%" onclick="reconcileAccount('${a.id}')">Check actual balance</button></div>`}).join('')}</div><div class="panel section-gap"><div class="panel-head"><div><h2>Balance integrity</h2><p class="help-copy">Reconciliation helps catch missing entries without hiding the difference.</p></div><span>Local ledger</span></div><div class="metric-line"><span>Total across accounts</span><strong>${money(totalCash())}</strong></div><div class="metric-line"><span>Last local backup</span><strong>Just now</strong></div></div>`}
function render(){nav();document.body.classList.toggle('review-mode',review);document.getElementById('eyebrow').textContent=current;document.getElementById('pageTitle').textContent=current==='Overview'?'Your money, in focus':current;const views={Overview:dashboard,Transactions:transactions,Accounts:accounts,Budget:budget,Savings:savings,Investments:investments,Reports:reports,Settings:settings};document.getElementById('app').innerHTML=views[current]();if(current==='Settings')document.getElementById('app').insertAdjacentHTML('beforeend',managePanel());if(current==='Overview')document.getElementById('app').insertAdjacentHTML('beforeend',quickActions())}

if(!state.recurring)state.recurring=[];
function today(){return new Date().toISOString().slice(0,10)}
function recurring(){return`<div class="view-head"><div><div class="kicker">Set it once</div><h1>Recurring money</h1><p>Prepare regular income, bills, savings, and investments so you do not have to remember them every time.</p></div><button class="primary-button" onclick="openRecurringModal()">＋ Add recurring</button></div><div class="panel"><div class="panel-head"><div><h2>Your recurring items</h2><p class="help-copy">Nothing is added automatically without your confirmation.</p></div><span>${state.recurring.length} scheduled</span></div>${state.recurring.length?state.recurring.map(r=>`<div class="recurring-card"><div class="recurring-icon">↻</div><div class="recurring-main"><strong>${r.description}</strong><small>${r.type} · ${r.category} · day ${r.day} each month · ${state.accounts.find(a=>a.id===r.account)?.name||'—'}</small></div><strong>${money(r.amount)}</strong><button class="edit-button" onclick="applyRecurring('${r.id}')">Add now</button><button class="edit-button danger" onclick="deleteRecurring('${r.id}')">Delete</button></div>`).join(''):'<div class="empty"><strong>No recurring items yet</strong>Add your salary, bills, or savings contribution once and reuse them each month.</div>'}</div>`}
function openRecurringModal(){const fields=field('Description','description','','text',true)+selectField('Type','type',[['expense','Money out'],['income','Money in'],['transfer','Move between accounts']],'expense')+field('Category','category','Bills')+field('Amount · PHP','amount','','number')+field('Day of month','day',1,'number')+selectField('Account','account',state.accounts.map(a=>[a.id,a.name]),state.accounts[0]?.id,true);modalShell('Add recurring item','Set up something that happens regularly. You can add it to the ledger when you are ready.',fields);document.getElementById('entityForm').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);state.recurring.push({id:'r'+Date.now(),description:f.get('description'),type:f.get('type'),category:f.get('category'),amount:Number(f.get('amount')),day:Math.max(1,Math.min(28,Number(f.get('day')))),account:f.get('account')});save();closeModal();render()}}
function applyRecurring(id){const r=state.recurring.find(x=>x.id===id);if(!r)return;const date=`${month}-${String(r.day).padStart(2,'0')}`;if(state.transactions.some(t=>t.recurringId===id&&t.date===date)){showToast('Already added','This recurring item is already in the current month.');return}state.transactions.push({id:'t'+Date.now(),recurringId:id,date,description:r.description,category:r.category,account:r.account,type:r.type,direction:r.type==='transfer'?'out':undefined,amount:r.amount});save();current='Transactions';render()}
function deleteRecurring(id){if(!confirm('Remove this recurring item?'))return;state.recurring=state.recurring.filter(r=>r.id!==id);save();render()}
function setQuick(category,amount){const form=document.getElementById('entityForm');if(form){form.category.value=category;form.amount.value=amount}}
function openModal(){const fields=transactionFields();modalShell('Add transaction','A few details is all Ledger needs to keep your totals accurate.',fields);document.querySelector('#entityForm .form-grid').insertAdjacentHTML('afterbegin','<div class="field full"><label>Quick start</label><div class="quick-entry"><button type="button" onclick="setQuick(\'Food\',150)">Food · ₱150</button><button type="button" onclick="setQuick(\'Transport\',50)">Transport · ₱50</button><button type="button" onclick="setQuick(\'Bills\',500)">Bills · ₱500</button><button type="button" onclick="setQuick(\'Wants\',100)">Wants · ₱100</button></div></div>');document.getElementById('entityForm').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);state.transactions.push({id:'t'+Date.now(),date:f.get('date'),description:f.get('description'),category:f.get('category'),account:f.get('account'),type:f.get('type'),direction:f.get('direction'),amount:Number(f.get('amount'))});save();closeModal();current='Transactions';render()}}
function accountBalance(id){const a=state.accounts.find(x=>x.id===id);return(a?.opening||0)+state.transactions.filter(t=>t.account===id).reduce((s,t)=>s+(t.type==='income'||(t.type==='transfer'&&t.direction==='in')||(t.type==='adjustment'&&t.direction==='in')?t.amount:-t.amount),0)}
function reconcileAccount(id){const a=state.accounts.find(x=>x.id===id);if(!a)return;modalShell(`Reconcile ${a.name}`,'Compare Ledger with the balance shown in your bank or wallet.');document.querySelector('#entityForm .form-grid').innerHTML=field('Ledger balance','ledger',accountBalance(id),'number',true)+field('Actual balance','actual',accountBalance(id),'number',true)+'<div class="field full"><p class="help-copy">If there is a difference, Ledger will create a separate adjustment record. It will not change your income or spending totals.</p></div>';document.getElementById('entityForm').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);const diff=Number(f.get('actual'))-Number(f.get('ledger'));if(Math.abs(diff)>0.005)state.transactions.push({id:'t'+Date.now(),date:today(),description:'Reconciliation adjustment',category:'Reconciliation',account:id,type:'adjustment',direction:diff>0?'in':'out',amount:Math.abs(diff)});save();closeModal();current='Accounts';render()}}
function accounts(){return`<div class="view-head"><div><div class="kicker">Where money lives</div><h1>Accounts</h1><p>Bank accounts, e-wallets, and cash—kept visible and easy to check.</p></div><button class="primary-button" onclick="addAccount()">＋ Add account</button></div><div class="grid grid-3">${state.accounts.map(a=>`<div class="account-card"><div class="account-top"><div><h3>${a.name}</h3><small>${a.type}</small></div><span class="badge green">active</span></div><div class="balance">${money(accountBalance(a.id))}</div><small>Opening ${money(a.opening)} · derived from ledger</small><button class="ghost-button" style="margin-top:15px;width:100%" onclick="reconcileAccount('${a.id}')">Check actual balance</button></div>`).join('')}</div><div class="panel section-gap"><div class="panel-head"><div><h2>Balance integrity</h2><p class="help-copy">Reconciliation helps catch missing entries without hiding the difference.</p></div><span>Local ledger</span></div><div class="metric-line"><span>Total across accounts</span><strong>${money(totalCash())}</strong></div><div class="metric-line"><span>Last local backup</span><strong>Just now</strong></div></div>`}
function budget(){const planned=state.budgets.reduce((s,b)=>s+b.limit,0);const over=state.budgets.find(b=>budgetSpent(b)>b.limit);return`<div class="view-head"><div><div class="kicker">October 2026</div><h1>Budget</h1><p>Simple category limits with a clear view of what remains.</p></div><button class="primary-button" onclick="addBudget()">＋ Add category</button></div><div class="grid grid-4">${stat('Planned',money(planned),'Monthly limits')}${stat('Spent',money(expenses()),'This month',true)}${stat('Remaining',money(planned-expenses()),over?'Review overspending':'Before overspend')}${stat('Savings rate',`${income()?Math.round((income()-expenses())/income()*100):0}%`,'Based on income')}</div>${over?`<div class="notice section-gap">Your ${over.category} budget is over the limit. You can edit the limit or review the transactions below.</div>`:''}<div class="panel section-gap">${state.budgets.map(b=>`<div class="budget-row"><div class="budget-label"><strong>${b.category}</strong><span>${money(budgetSpent(b))} spent · ${money(Math.max(0,b.limit-budgetSpent(b)))} left</span></div><div class="bar"><span style="width:${Math.min(100,budgetSpent(b)/b.limit*100)}%;background:${budgetSpent(b)>b.limit?'var(--red)':'var(--accent)'}"></span></div></div>`).join('')}</div>`}
function savings(){return`<div class="view-head"><div><div class="kicker">Build your buffer</div><h1>Savings goals</h1><p>Small, consistent contributions become options later.</p></div><button class="primary-button" onclick="addGoal()">＋ Add goal</button></div><div class="grid grid-2">${state.goals.map(g=>{const months=Math.max(1,Math.ceil((new Date(g.due)-new Date())/(30*86400000)));const monthly=Math.max(0,(g.target-g.current)/months);const pct=Math.min(100,g.current/g.target*100);return`<div class="panel"><div class="panel-head"><h2>${g.name}</h2><span>${Math.round(pct)}%</span></div><div class="bar"><span style="width:${pct}%;background:var(--green)"></span></div><div class="metric-line"><span>Saved</span><strong>${money(g.current)}</strong></div><div class="metric-line"><span>Suggested monthly amount</span><strong>${money(monthly)}</strong></div><div class="metric-line"><span>Target date</span><strong>${new Date(g.due).toLocaleDateString('en-PH',{month:'short',year:'numeric'})}</strong></div><div class="on-track">${pct>=50?'You are building momentum':'Start small and stay consistent'}</div></div>`}).join('')}</div>`}
function reports(){const contributed=state.investments.reduce((s,i)=>s+i.cost,0);return`<div class="view-head"><div><div class="kicker">Understand the pattern</div><h1>Reports</h1><p>Lightweight views that help you notice habits without overwhelming you.</p></div></div><div class="grid grid-2"><div class="panel"><div class="panel-head"><h2>Monthly summary</h2><span>October 2026</span></div><div class="metric-line"><span>Money in</span><strong class="amount income">${money(income())}</strong></div><div class="metric-line"><span>Money out</span><strong class="amount expense">${money(expenses())}</strong></div><div class="metric-line"><span>Net movement</span><strong>${money(income()-expenses())}</strong></div><div class="metric-line"><span>Available cash</span><strong>${money(totalCash())}</strong></div></div><div class="panel"><div class="panel-head"><h2>Spending by category</h2><span>This month</span></div>${state.budgets.map(b=>`<div class="report-bar"><label>${b.category}</label><div class="bar"><span style="width:${Math.min(100,expenses()?budgetSpent(b)/Math.max(...state.budgets.map(x=>budgetSpent(x)),1)*100:0)}%"></span></div><strong>${money(budgetSpent(b))}</strong></div>`).join('')}</div></div><div class="grid grid-3 section-gap"><div class="panel"><div class="panel-head"><h2>Net worth snapshot</h2></div><div class="metric-line"><span>Cash accounts</span><strong>${money(totalCash())}</strong></div><div class="metric-line"><span>Investments</span><strong>${money(investmentValue())}</strong></div><div class="metric-line"><span>Total tracked</span><strong>${money(totalCash()+investmentValue())}</strong></div></div><div class="panel"><div class="panel-head"><h2>Long-term contributions</h2></div><div class="metric-line"><span>Invested so far</span><strong>${money(contributed)}</strong></div><div class="metric-line"><span>Current value</span><strong>${money(investmentValue())}</strong></div></div><div class="panel"><div class="panel-head"><h2>Helpful reminder</h2></div><p class="help-copy">Reports show patterns, not judgments. Use them to decide one small improvement for the next week.</p></div></div>`}

function settings(){return`<div class="view-head"><div><div class="kicker">Your workspace</div><h1>Settings</h1><p>Keep Ledger comfortable, private, and easy to recover.</p></div></div><div class="grid grid-2"><div class="panel"><div class="panel-head"><h2>Appearance</h2></div><div class="metric-line"><span>Theme</span><button class="ghost-button" onclick="toggleTheme()">Toggle light / dark</button></div><div class="metric-line"><span>Detail mode</span><button class="ghost-button" onclick="setMode(!review)">${review?'Review':'Simple'}</button></div></div><div class="panel"><div class="panel-head"><div><h2>Data safety</h2><p class="help-copy">Your data stays on this device unless you export it.</p></div></div><div class="metric-line"><span>Storage</span><strong>Local browser storage</strong></div><div class="metric-line"><span>Export backup</span><button class="ghost-button" onclick="exportData()">Download JSON</button></div><div class="metric-line"><span>Export transactions</span><button class="ghost-button" onclick="exportCsv()">Download CSV</button></div><div class="metric-line"><span>Restore backup</span><label class="ghost-button file-button">Choose JSON<input type="file" id="restoreFile" accept="application/json" onchange="restoreData(this)"></label></div><div class="notice">Ledger keeps an automatic previous backup whenever you save a change.</div></div></div>`}
function exportCsv(){const rows=[['Date','Description','Category','Account','Type','Amount'],...state.transactions.map(t=>[t.date,t.description,t.category,state.accounts.find(a=>a.id===t.account)?.name||'',t.type,t.amount])];const csv=rows.map(row=>row.map(v=>`"${String(v).replace(/"/g,'""')}"`).join(',')).join('\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));a.download='ledger-transactions.csv';a.click();URL.revokeObjectURL(a.href);showToast('CSV exported','Your transaction list is ready.')}
function restoreData(input){const file=input.files?.[0];if(!file)return;const reader=new FileReader();reader.onload=()=>{try{const imported=JSON.parse(reader.result);if(!imported.accounts||!imported.transactions)throw new Error('missing data');localStorage.setItem(KEY+'-backup',JSON.stringify(state));state={...imported,recurring:imported.recurring||[]};localStorage.setItem(KEY,JSON.stringify(state));showToast('Backup restored','Your workspace has been updated.');render()}catch(e){alert('That file does not look like a Ledger backup.')}};reader.readAsText(file)}
function resetData(){if(!confirm('Reset Ledger to the sample workspace? Your current data will be backed up first.'))return;localStorage.setItem(KEY+'-backup',JSON.stringify(state));state=JSON.parse(JSON.stringify(seed));state.recurring=[];localStorage.setItem(KEY,JSON.stringify(state));showToast('Workspace reset','Your previous data is available as a backup.');render()}
function save(){const previous=localStorage.getItem(KEY);if(previous)localStorage.setItem(KEY+'-backup',previous);localStorage.setItem(KEY,JSON.stringify(state));document.getElementById('backupLabel').textContent='Saved just now';showToast('Saved','Your changes are stored on this device.')}
function openSetup(){document.getElementById('modalRoot').innerHTML=`<div class="setup-backdrop"><div class="setup-card"><div class="kicker">Welcome to Ledger</div><h2>Let’s make money easier to see.</h2><p>Set up the basics once. You can change everything later from inside the app. Nothing leaves this device.</p><div class="setup-steps"><div class="setup-step"><strong>1. Track daily</strong><span>Add an expense in seconds.</span></div><div class="setup-step"><strong>2. Stay on track</strong><span>See what is left in each budget.</span></div><div class="setup-step"><strong>3. Grow steadily</strong><span>Build savings and investments.</span></div></div><form id="setupForm"><div class="form-grid">${field('Your main account','accountName','My bank','text',true)}${field('Starting balance · PHP','opening',0,'number')}${field('Usual monthly income · PHP','income',0,'number','full')}</div><div class="modal-actions"><button type="button" class="ghost-button" onclick="finishSetup(true)">Explore sample workspace</button><button class="primary-button">Set up my workspace</button></div></form></div></div>`;document.getElementById('setupForm').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);finishSetup(false,f)}}
function finishSetup(sample,f){if(sample){state=JSON.parse(JSON.stringify(seed));state.recurring=[]}else{const opening=Number(f.get('opening')||0),monthly=Number(f.get('income')||0);state={accounts:[{id:'a1',name:f.get('accountName')||'My account',type:'Bank account',opening}],transactions:monthly?[{id:'t'+Date.now(),date:today(),description:'Monthly income',category:'Income',account:'a1',type:'income',amount:monthly}]:[],budgets:[{category:'Food',limit:Math.round(monthly*.12)},{category:'Bills',limit:Math.round(monthly*.2)},{category:'Transport',limit:Math.round(monthly*.08)},{category:'Wants',limit:Math.round(monthly*.1)}],goals:[{id:'g1',name:'Emergency fund',target:monthly*3,current:0,due:'2027-06-30'}],investments:[],recurring:[]}}localStorage.setItem(KEY,JSON.stringify(state));localStorage.setItem(KEY+'-backup',JSON.stringify(state));document.getElementById('modalRoot').innerHTML='';showToast('Workspace ready','You can change these details any time.');render()}
function maybeSetup(){if(!localStorage.getItem(KEY)&&!document.querySelector('.setup-backdrop'))setTimeout(openSetup,250)}
function render(){nav();document.body.classList.toggle('review-mode',review);document.getElementById('eyebrow').textContent=current;document.getElementById('pageTitle').textContent=current==='Overview'?'Your money, in focus':current;const views={Overview:dashboard,Transactions:transactions,Accounts:accounts,Budget:budget,Savings:savings,Investments:investments,Recurring:recurring,Reports:reports,Settings:settings};document.getElementById('app').innerHTML=views[current]();if(current==='Settings')document.getElementById('app').insertAdjacentHTML('beforeend',managePanel());if(current==='Overview')document.getElementById('app').insertAdjacentHTML('beforeend',quickActions());maybeSetup()}
function openSetup(){document.getElementById('modalRoot').innerHTML=`<div class="setup-backdrop"><div class="setup-card"><div class="kicker">Welcome to Ledger</div><h2>Start with your real numbers.</h2><p>There are no sample accounts, transactions, budgets, goals, or investments. Enter only what you currently have; you can add the rest later.</p><div class="setup-steps"><div class="setup-step"><strong>1. Your account</strong><span>Enter one account you currently use.</span></div><div class="setup-step"><strong>2. Your starting point</strong><span>Add your actual balance and income.</span></div><div class="setup-step"><strong>3. Add as you go</strong><span>Create budgets and goals when ready.</span></div></div><form id="setupForm"><div class="form-grid">${field('Account name','accountName','','text',true)}${field('Current balance · PHP','opening','','number')}${field('Monthly income · PHP','income','','number','full')}</div><div class="modal-actions"><button class="primary-button">Start my empty workspace</button></div></form></div></div>`;document.getElementById('setupForm').onsubmit=e=>{e.preventDefault();finishSetup(false,new FormData(e.target))}}
function finishSetup(sample,f){const accountName=String(f.get('accountName')||'').trim();const opening=Number(f.get('opening')||0);const monthly=Number(f.get('income')||0);const accountId='a'+Date.now();state={accounts:[{id:accountId,name:accountName,type:'Bank account',opening}],transactions:monthly?[{id:'t'+Date.now(),date:today(),description:'Monthly income',category:'Income',account:accountId,type:'income',amount:monthly}]:[],budgets:[],goals:[],investments:[],recurring:[]};localStorage.setItem(KEY,JSON.stringify(state));localStorage.setItem(KEY+'-backup',JSON.stringify(state));document.getElementById('modalRoot').innerHTML='';showToast('Workspace ready','Only the values you entered were saved.');render()}
function resetData(){if(!confirm('Clear all Ledger data? This removes accounts, transactions, budgets, goals, investments, recurring items, and backups.'))return;localStorage.removeItem(KEY);localStorage.removeItem(KEY+'-backup');state={accounts:[],transactions:[],budgets:[],goals:[],investments:[],recurring:[]};showToast('Workspace cleared','You can now enter your current information from scratch.');render()}
function save(){const previous=localStorage.getItem(KEY);if(previous)localStorage.setItem(KEY+'-backup',previous);localStorage.setItem(KEY,JSON.stringify(state));document.getElementById('backupLabel').textContent='Saving locally…';if(location.protocol!=='file:'){fetch('/api/state',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(state)}).then(response=>{if(!response.ok)throw new Error('database save failed');document.getElementById('backupLabel').textContent='Database saved'}).catch(()=>{document.getElementById('backupLabel').textContent='Saved locally'})}else{document.getElementById('backupLabel').textContent='Saved locally'}showToast('Saved','Your changes are stored locally.');createServerBackup()}
async function loadDatabaseState(){if(location.protocol==='file:')return;try{const response=await fetch('/api/state',{cache:'no-store'});const payload=await response.json();if(payload.state){state={...payload.state,recurring:payload.state.recurring||[]};localStorage.setItem(KEY,JSON.stringify(state));document.getElementById('modalRoot').innerHTML='';render()}else if(state.accounts.length||state.transactions.length||state.budgets.length||state.goals.length||state.investments.length){await fetch('/api/state',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(state)})}}catch{document.getElementById('backupLabel').textContent='Local mode'}}
if(location.protocol!=='file:')loadDatabaseState();
function finishSetup(sample,f){const accountName=String(f.get('accountName')||'').trim();const opening=Number(f.get('opening')||0);const monthly=Number(f.get('income')||0);const accountId='a'+Date.now();state={accounts:[{id:accountId,name:accountName,type:'Bank account',opening}],transactions:monthly?[{id:'t'+Date.now(),date:today(),description:'Monthly income',category:'Income',account:accountId,type:'income',amount:monthly}]:[],budgets:[],goals:[],investments:[],recurring:[]};document.getElementById('modalRoot').innerHTML='';save();showToast('Workspace ready','Your entries are now stored in the local database.');render()}
function restoreData(input){const file=input.files?.[0];if(!file)return;const reader=new FileReader();reader.onload=()=>{try{const imported=JSON.parse(reader.result);const data=imported.data||imported;if(!data.accounts||!data.transactions)throw new Error('missing data');state={...data,recurring:data.recurring||[]};save();showToast('Backup restored','The restored data is now in the local database.');render()}catch{alert('That file does not look like a Ledger backup.')}};reader.readAsText(file)}
function resetData(){if(!confirm('Clear all Ledger data? This removes the SQLite database state, accounts, transactions, budgets, goals, investments, recurring items, and backups.'))return;state={accounts:[],transactions:[],budgets:[],goals:[],investments:[],recurring:[]};localStorage.removeItem(KEY);localStorage.removeItem(KEY+'-backup');if(location.protocol!=='file:')fetch('/api/state',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(state)});showToast('Workspace cleared','You can start again with an empty local database.');render()}
function createServerBackup(manual=false){const label=document.getElementById('backupLabel');if(label)label.textContent='Saving backup…';return fetch('/api/backup',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(state)}).then(response=>{if(!response.ok)throw new Error('backup failed');return response.json()}).then(result=>{if(label)label.textContent='Backup saved';if(manual)showToast('Backup created',`${result.file} saved in the backups folder.`);return result}).catch(()=>{if(label)label.textContent='Saved locally';if(manual)showToast('Local save complete','Start the local server to create a file backup.')})}
function save(){const previous=localStorage.getItem(KEY);if(previous)localStorage.setItem(KEY+'-backup',previous);localStorage.setItem(KEY,JSON.stringify(state));document.getElementById('backupLabel').textContent='Saved locally';showToast('Saved','Your changes are stored on this device.');createServerBackup()}
function settings(){return`<div class="view-head"><div><div class="kicker">Your workspace</div><h1>Settings</h1><p>Keep Ledger comfortable, private, and easy to recover.</p></div></div><div class="grid grid-2"><div class="panel"><div class="panel-head"><h2>Appearance</h2></div><div class="metric-line"><span>Theme</span><button class="ghost-button" onclick="toggleTheme()">Toggle light / dark</button></div><div class="metric-line"><span>Detail mode</span><button class="ghost-button" onclick="setMode(!review)">${review?'Review':'Simple'}</button></div></div><div class="panel"><div class="panel-head"><div><h2>Data safety</h2><p class="help-copy">Every save writes to local storage and attempts a dated file backup.</p></div></div><div class="metric-line"><span>Storage</span><strong>Local browser storage</strong></div><div class="metric-line"><span>Save a backup now</span><button class="ghost-button" onclick="createServerBackup(true)">Create JSON backup</button></div><div class="metric-line"><span>Export backup</span><button class="ghost-button" onclick="exportData()">Download JSON</button></div><div class="metric-line"><span>Export transactions</span><button class="ghost-button" onclick="exportCsv()">Download CSV</button></div><div class="metric-line"><span>Restore backup</span><label class="ghost-button file-button">Choose JSON<input type="file" id="restoreFile" accept="application/json" onchange="restoreData(this)"></label></div><div class="notice">Automatic server backups are kept in the local <strong>backups</strong> folder, with the 20 most recent snapshots retained.</div></div></div>`}
function dashboard(){const recent=state.transactions.filter(t=>!query||`${t.description} ${t.category}`.toLowerCase().includes(query.toLowerCase())).sort((a,b)=>b.date.localeCompare(a.date)).slice(0,6);const goal=state.goals[0];const budgetMarkup=state.budgets.length?state.budgets.map(b=>`<div class="budget-row"><div class="budget-label"><strong>${b.category}</strong><span>${money(budgetSpent(b))} / ${money(b.limit)}</span></div><div class="bar"><span style="width:${b.limit?Math.min(100,budgetSpent(b)/b.limit*100):0}%;background:${budgetSpent(b)>b.limit?'var(--red)':'var(--accent)'}"></span></div></div>`).join(''):'<div class="empty"><strong>No budget categories yet</strong>Add your first category when you are ready.</div>';const goalMarkup=goal?`<div class="goal-card"><span class="muted">Next milestone</span><h3>${goal.name}</h3><div class="bar"><span style="width:${Math.min(100,goal.current/goal.target*100)}%"></span></div><div class="goal-foot"><span>${money(goal.current)} saved</span><strong>${Math.round(goal.current/goal.target*100)}%</strong></div></div>`:`<div class="goal-card"><span class="muted">Savings</span><h3>No savings goal yet</h3><p class="help-copy" style="color:#aaa59b">Create one when you know what you want to work toward.</p><button class="ghost-button" onclick="addGoal()">＋ Add a goal</button></div>`;const savingsMarkup=goal?`<div class="metric-line"><span>${goal.name}</span><strong>${money(goal.current)}</strong></div><div class="metric-line"><span>Target</span><strong>${money(goal.target)}</strong></div><div class="metric-line"><span>Progress</span><strong>${Math.round(goal.current/goal.target*100)}%</strong></div>`:'<div class="empty"><strong>No savings goals yet</strong>Your progress will appear here after you add one.</div>';return`<div class="view-head"><div><div class="kicker">October 2026 · local workspace</div><h1>Your money, in focus.</h1><p>A calm place to see what came in, what went out, and what matters next.</p></div><div class="view-actions"><div class="mode-toggle"><button class="${!review?'active':''}" onclick="setMode(false)">Simple</button><button class="${review?'active':''}" onclick="setMode(true)">Review</button></div></div></div><div class="grid grid-4">${stat('Available across accounts',money(totalCash()),state.accounts.length?'All local accounts':'Add an account to begin')}${stat('Money in',money(income()),'This month')}${stat('Money out',money(expenses()),'This month',true)}${stat('Investments',money(investmentValue()),state.investments.length?'Current value':'Add holdings when ready')}</div><div class="grid grid-2 section-gap"><div class="panel"><div class="panel-head"><h2>Recent activity</h2><button onclick="go('Transactions')">View all →</button></div>${activity(recent)}</div><div class="panel"><div class="panel-head"><h2>Monthly budget</h2><button onclick="go('Budget')">Open budget →</button></div>${budgetMarkup}</div></div><div class="grid grid-3 section-gap">${goalMarkup}<div class="panel"><div class="panel-head"><h2>Savings pulse</h2><span>Your progress</span></div>${savingsMarkup}</div><div class="panel"><div class="panel-head"><h2>Money flow</h2><span>Build your history</span></div><div class="empty"><strong>No chart yet</strong>Add transactions over time and your spending pattern will appear here.</div></div></div>`}

function exportData(){const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='savedatcost-backup.json';a.click();URL.revokeObjectURL(a.href)}
function exportCsv(){const rows=[['Date','Description','Category','Account','Type','Amount'],...state.transactions.map(t=>[t.date,t.description,t.category,state.accounts.find(a=>a.id===t.account)?.name||'',t.type,t.amount])];const csv=rows.map(row=>row.map(v=>`"${String(v).replace(/"/g,'""')}"`).join(',')).join('\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));a.download='savedatcost-transactions.csv';a.click();URL.revokeObjectURL(a.href);showToast('CSV exported','Your transaction list is ready.')}

(function applySavedatCostBranding(){
  const replace = value => value.replace(/Ledger/g,'SavedatCost').replace(/ledger-/g,'savedatcost-');
  const scan = root => {
    const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT);
    const nodes = [];
    while (walker.nextNode()) nodes.push(walker.currentNode);
    nodes.forEach(node => { const next = replace(node.nodeValue); if (next !== node.nodeValue) node.nodeValue = next; });
    root.querySelectorAll?.('[title],[placeholder],[aria-label]').forEach(element => ['title','placeholder','aria-label'].forEach(attribute => { if (element.hasAttribute(attribute)) element.setAttribute(attribute, replace(element.getAttribute(attribute))); }));
  };
  scan(document.body);
  new MutationObserver(records => records.forEach(record => {
    if (record.type === 'characterData') { const next = replace(record.target.nodeValue); if (next !== record.target.nodeValue) record.target.nodeValue = next; }
    record.addedNodes.forEach(node => { if (node.nodeType === Node.TEXT_NODE) { const next = replace(node.nodeValue); if (next !== node.nodeValue) node.nodeValue = next; } else if (node.nodeType === Node.ELEMENT_NODE) scan(node); });
  })).observe(document.body,{subtree:true,childList:true,characterData:true});
})();

function reviewPanel(){
  const currentValue=investmentValue(), contributed=state.investments.reduce((sum,item)=>sum+Number(item.cost||0),0);
  const remaining=state.budgets.reduce((sum,item)=>sum+Number(item.limit||0),0)-expenses();
  return `<section class="review-inspector section-gap"><div class="review-inspector-head"><div><span class="review-eyebrow">Detailed review</span><h2>Calculation inspector</h2><p>Review mode is on. These are the numbers behind this screen.</p></div><span class="review-badge">REVIEW ON</span></div><div class="review-grid"><div><span>Accounts tracked</span><strong>${state.accounts.length}</strong></div><div><span>Transactions tracked</span><strong>${state.transactions.length}</strong></div><div><span>Budget remaining</span><strong>${money(remaining)}</strong></div><div><span>Investment gain / loss</span><strong class="${currentValue>=contributed?'review-positive':'review-negative'}">${money(currentValue-contributed)}</strong></div></div><div class="review-formula"><strong>How SavedatCost calculates totals</strong><span>Account balance = opening balance + money in − money out. Budget remaining = monthly limits − this month’s categorized expenses. Investment gain/loss = current value − contributed amount.</span></div></section>`;
}

function injectReviewPanel(){const app=document.getElementById('app');if(!app||!document.body.classList.contains('review-mode')||app.querySelector('.review-inspector'))return;app.insertAdjacentHTML('beforeend',reviewPanel())}
const reviewObserver=new MutationObserver(injectReviewPanel);
reviewObserver.observe(document.getElementById('app'),{childList:true,subtree:true});
injectReviewPanel();

let calculatorState={display:'0',previous:null,operator:null,waiting:false,memory:0};
function calculatorReset(){calculatorState={display:'0',previous:null,operator:null,waiting:false,memory:calculatorState.memory||0};calculatorRender()}
function calculatorNumber(value){if(calculatorState.waiting){calculatorState.display=value;calculatorState.waiting=false}else{calculatorState.display=calculatorState.display==='0'?value:calculatorState.display+value}calculatorRender()}
function calculatorDecimal(){if(calculatorState.waiting){calculatorState.display='0.';calculatorState.waiting=false}else if(!calculatorState.display.includes('.'))calculatorState.display+='.';calculatorRender()}
function calculatorOperate(first,second,operator){if(operator==='+')return first+second;if(operator==='−')return first-second;if(operator==='×')return first*second;if(operator==='÷')return second===0?NaN:first/second;return second}
function calculatorEquals(){const current=Number(calculatorState.display);if(calculatorState.previous!==null&&calculatorState.operator){const result=calculatorOperate(calculatorState.previous,current,calculatorState.operator);calculatorState.display=Number.isFinite(result)?String(Number(result.toFixed(10))):'Error';calculatorState.previous=null;calculatorState.operator=null;calculatorState.waiting=true}calculatorRender()}
function calculatorPress(action){if(/^\d$/.test(action)){calculatorNumber(action);return}if(action==='decimal'){calculatorDecimal();return}if(['+','−','×','÷'].includes(action)){const current=Number(calculatorState.display);if(calculatorState.previous!==null&&calculatorState.operator&&!calculatorState.waiting){const result=calculatorOperate(calculatorState.previous,current,calculatorState.operator);calculatorState.display=Number.isFinite(result)?String(Number(result.toFixed(10))):'Error'}calculatorState.previous=Number(calculatorState.display);calculatorState.operator=action;calculatorState.waiting=true;calculatorRender();return}if(action==='equals'){calculatorEquals();return}if(action==='clear'){calculatorReset();return}if(action==='backspace'){if(!calculatorState.waiting)calculatorState.display=calculatorState.display.length>1?calculatorState.display.slice(0,-1):'0';calculatorRender();return}if(action==='percent'){calculatorState.display=String(Number(calculatorState.display)/100);calculatorRender();return}if(action==='sign'){if(calculatorState.display!=='0')calculatorState.display=calculatorState.display.startsWith('-')?calculatorState.display.slice(1):'-'+calculatorState.display;calculatorRender();return}if(action==='sqrt'){const result=Math.sqrt(Number(calculatorState.display));calculatorState.display=Number.isFinite(result)?String(Number(result.toFixed(10))):'Error';calculatorState.waiting=true;calculatorRender();return}if(action==='square'){const result=Number(calculatorState.display)**2;calculatorState.display=String(Number(result.toFixed(10)));calculatorState.waiting=true;calculatorRender();return}if(action==='reciprocal'){const result=1/Number(calculatorState.display);calculatorState.display=Number.isFinite(result)?String(Number(result.toFixed(10))):'Error';calculatorState.waiting=true;calculatorRender();return}if(action==='memory-clear'){calculatorState.memory=0;calculatorRender();return}if(action==='memory-recall'){calculatorState.display=String(calculatorState.memory);calculatorState.waiting=true;calculatorRender();return}if(action==='memory-add'){calculatorState.memory+=Number(calculatorState.display)||0;calculatorState.waiting=true;calculatorRender();return}if(action==='memory-subtract'){calculatorState.memory-=Number(calculatorState.display)||0;calculatorState.waiting=true;calculatorRender();return}}
function calculatorRender(){const display=document.getElementById('calcDisplay');if(display)display.textContent=calculatorState.display;const memory=document.getElementById('calcMemory');if(memory)memory.textContent=calculatorState.memory?'M':''}
function calcKey(label,action,extra=''){return`<button type="button" class="calc-key ${extra}" onclick="calculatorPress('${action}')">${label}</button>`}
function openCalculator(){calculatorState={display:'0',previous:null,operator:null,waiting:false,memory:calculatorState.memory||0};document.getElementById('modalRoot').innerHTML=`<div class="modal-backdrop" onclick="if(event.target===this)closeModal()"><div class="calculator-modal" role="dialog" aria-label="Calculator"><div class="calculator-head"><div><span class="calculator-kicker">SavedatCost utility</span><h2>Calculator</h2></div><button class="close" onclick="closeModal()" aria-label="Close calculator">×</button></div><div class="calc-display-wrap"><span id="calcMemory" class="calc-memory"></span><output id="calcDisplay" class="calc-display">0</output></div><div class="calc-memory-row">${calcKey('MC','memory-clear','calc-memory-key')}${calcKey('MR','memory-recall','calc-memory-key')}${calcKey('M+','memory-add','calc-memory-key')}${calcKey('M−','memory-subtract','calc-memory-key')}</div><div class="calc-grid">${calcKey('AC','clear','calc-action')}${calcKey('⌫','backspace','calc-action')}${calcKey('%','percent','calc-action')}${calcKey('÷','÷','calc-operator')}${calcKey('√','sqrt','calc-action')}${calcKey('x²','square','calc-action')}${calcKey('1/x','reciprocal','calc-action')}${calcKey('×','×','calc-operator')}${calcKey('7','7')}${calcKey('8','8')}${calcKey('9','9')}${calcKey('−','−','calc-operator')}${calcKey('4','4')}${calcKey('5','5')}${calcKey('6','6')}${calcKey('+','+','calc-operator')}${calcKey('1','1')}${calcKey('2','2')}${calcKey('3','3')}${calcKey('±','sign','calc-action')}${calcKey('0','0','calc-zero')}${calcKey('.','decimal')}${calcKey('=','equals','calc-equals')}</div><p class="calculator-note">For quick estimates only. SavedatCost does not save calculator entries.</p></div></div>`;calculatorRender()}
const calculatorButton=document.getElementById('calculatorBtn');if(calculatorButton)calculatorButton.onclick=openCalculator;

function referenceHero(){return `<section class="reference-hero" aria-label="SavedatCost overview"><div class="reference-hero-copy"><div class="reference-kicker"><span></span> YOUR LOCAL FINANCE WORKSPACE</div><h2>Spend less guessing.<br><em>More planning.</em></h2><p>Your next money decision is clearer than you think. Track every peso, build a buffer, and keep your long-term goals visible.</p><div class="reference-meta"><strong>₱ Local-first</strong><strong>↗ Reviewable totals</strong></div></div><div class="reference-orbit"><div class="orbit-ring orbit-ring-one"></div><div class="orbit-ring orbit-ring-two"></div><div class="orbit-logo"><div class="orbit-logo-symbol">₱</div><span>SavedatCost</span></div><div class="orbit-caption">CURRENT BALANCE</div><strong>${money(totalCash())}</strong></div></section>`}
function injectReferenceHero(){const app=document.getElementById('app');if(!app||current!=='Overview'||app.querySelector('.reference-hero'))return;app.insertAdjacentHTML('afterbegin',referenceHero())}
const referenceObserver=new MutationObserver(injectReferenceHero);
referenceObserver.observe(document.getElementById('app'),{childList:true});
injectReferenceHero();

function quickActions(){return`<div class="panel section-gap"><div class="panel-head"><div><h2>What would you like to do?</h2><p class="help-copy">Keep your routine simple: record today, then check what is left.</p></div><span>Quick actions</span></div><div class="quick-actions"><button class="primary-button" onclick="openModal()">＋ Add expense</button><button class="ghost-button" onclick="openEntityModal('goal')">＋ Start savings goal</button><button class="ghost-button" onclick="go('Budget')">Review budget →</button><button class="ghost-button" onclick="go('Accounts')">Check accounts →</button><button class="ghost-button" onclick="openCalculator()">⌗ Calculator</button></div></div>`}
